fullnameOverride: ""

global:
  projectName: free5gc

initcontainers:
  curl:
    registry: towards5gs
    image: initcurl
    tag: "1.0.0"
  busybox:
    image: busybox
    tag: "1.32.0"

mongodb:
  service:
    name: mongodb
    type: ClusterIP
    port: 27017
    nodePort: "30017"

dbpython:
  name: dbpython
  replicaCount: 1
  image:
    name: towards5gs/free5gc-dbpython
    pullPolicy: IfNotPresent
  podAnnotations: {}
  imagePullSecrets: []
  podSecurityContext:
    seccompProfile:
      type: RuntimeDefault
  securityContext: {}
  resources:
    limits:
      cpu: 100m
      memory: 128Mi
    requests:
      cpu: 100m
      memory: 128Mi
  readinessProbe:
    enabled: true
    exec:
      command:
        - "true"
    initialDelaySeconds: 10
    periodSeconds: 1
    timeoutSeconds: 1
    failureThreshold:  40
    successThreshold: 1
  livenessProbe:
    enabled: true
    exec:
      command:
        - "true"
    initialDelaySeconds: 50
    periodSeconds: 10
    timeoutSeconds: 10
    failureThreshold: 3
    successThreshold: 1
  nodeSelector: {}
  tolerations: []
  affinity: {}
---
