cat > /home/vagrant/work/deploy/add-subscriber.js <<'EOF'
// Provision UE subscriber imsi-208930000000001 into free5gc DB (same document shapes as free5gc-dbpython add_subscribers.py)
const d = db.getSiblingDB('free5gc');
const ueId = 'imsi-208930000000001';
const plmn = '20893';
const sst = 1, sd = '010203', dnn = 'internet';
const keyK = '8baf473f2f8fd09487cccbd7097c6862';
const keyOPc = '8e27b6af0e692e750f32667a3b14605d';

const docs = {
  'subscriptionData.provisionedData.smfSelectionSubscriptionData': {
    ueId, servingPlmnId: plmn,
    subscribedSnssaiInfos: { '01010203': { dnnInfos: [{ dnn }] } }
  },
  'subscriptionData.provisionedData.smData': {
    ueId, servingPlmnId: plmn,
    singleNssai: { sst, sd },
    dnnConfigurations: { [dnn]: {
      '5gQosProfile': { '5qi': 9, arp: { preemptCap: 'NOT_PREEMPT', preemptVuln: 'NOT_PREEMPTABLE', priorityLevel: 8 }, priorityLevel: 8 },
      pduSessionTypes: { allowedSessionTypes: ['IPV4'], defaultSessionType: 'IPV4' },
      sessionAmbr: { downlink: '100 Mbps', uplink: '200 Mbps' },
      sscModes: { allowedSscModes: ['SSC_MODE_2', 'SSC_MODE_3'], defaultSscMode: 'SSC_MODE_1' }
    } }
  },
  'policyData.ues.smData': {
    ueId,
    smPolicySnssaiData: { '01010203': { snssai: { sst, sd }, smPolicyDnnData: { [dnn]: { dnn } } } }
  },
  'policyData.ues.amData': {
    ueId, subscCats: ['free5gc']
  },
  'subscriptionData.provisionedData.amData': {
    ueId, servingPlmnId: plmn,
    gpsis: ['msisdn-0900000000'],
    nssai: { defaultSingleNssais: [{ sst, sd }] },
    subscribedUeAmbr: { downlink: '2 Gbps', uplink: '1 Gbps' }
  },
  'subscriptionData.authenticationData.authenticationSubscription': {
    ueId,
    authenticationMethod: '5G_AKA',
    authenticationManagementField: '8000',
    milenage: { op: { encryptionAlgorithm: 0, encryptionKey: 0, opValue: '' } },
    opc: { encryptionAlgorithm: 0, encryptionKey: 0, opcValue: keyOPc },
    permanentKey: { encryptionAlgorithm: 0, encryptionKey: 0, permanentKeyValue: keyK },
    sequenceNumber: '16f3b3f70fc2'
  }
};

for (const [col, doc] of Object.entries(docs)) {
  const filter = (col === 'subscriptionData.provisionedData.smfSelectionSubscriptionData' || col === 'subscriptionData.provisionedData.smData' || col === 'subscriptionData.provisionedData.amData')
    ? { ueId, servingPlmnId: plmn } : { ueId };
  const r = d[col].replaceOne(filter, doc, { upsert: true });
  print(col, JSON.stringify(r));
}
print('count authenticationSubscription for', ueId, ':', d['subscriptionData.authenticationData.authenticationSubscription'].countDocuments({ ueId }));
EOF
cd /home/vagrant/work/deploy && kubectl exec -i -n free5gc mongodb-0 -c mongodb -- mongosh --quiet free5gc < add-subscriber.js 2>&1 | tail -12

